from jsonb_to_recordset($json$[{"id":"che-so-161","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A clear drop in vapour pressure is used as a colligative effect when the added solute is","options":["non-volatile (or far less volatile than the solvent)","more volatile than the solvent","a catalyst","always a noble gas"],"answer_index":0,"explanation":"Only then does the total pressure fall below $p^\\circ$ of the pure solvent.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-162","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"For an ideal mix the vapour mole fraction of A is related to the liquid composition by","options":["$y_A = (p_A^\\circ x_A) / p_{\\mathrm{total}}$","$y_A = x_A$","$y_A = p_A^\\circ$","$y_A = K_H x_A$"],"answer_index":0,"explanation":"Combine Raoult ($p_A = p_A^\\circ x_A$) with Dalton ($y_A = p_A / p_{\\mathrm{total}}$).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-163","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At a given temperature, the liquid with the larger $p^\\circ$ is described as","options":["more volatile","less volatile","non-volatile","ideal only"],"answer_index":0,"explanation":"Volatility tracks the equilibrium vapour pressure of the pure liquid.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-164","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Pure toluene has vapour pressure 30 torr. In an ideal mix with $x_{\\mathrm{toluene}} = 0.40$, the partial pressure of toluene is","options":["12 torr","30 torr","18 torr","70 torr"],"answer_index":0,"explanation":"$p = p^\\circ x = 30 \\times 0.40 = 12$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-165","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"An ideal pair has $p_A^\\circ = 80$ mm Hg and $p_B^\\circ = 20$ mm Hg. At $x_A = 0.50$ the total pressure is","options":["50 mm Hg","100 mm Hg","80 mm Hg","20 mm Hg"],"answer_index":0,"explanation":"$p = 80 \\times 0.50 + 20 \\times 0.50 = 50$ mm Hg.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-166","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Benzene ($p^\\circ = 75$ torr) plus a non-volatile solute form a liquid with $x_{\\mathrm{benzene}} = 0.90$. The vapour pressure of that solution is","options":["67.5 torr","75 torr","7.5 torr","83 torr"],"answer_index":0,"explanation":"Only benzene contributes: $p = 75 \\times 0.90 = 67.5$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-167","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Above an ideal liquid the partial pressure of A is 24 kPa while the total pressure is 60 kPa. The vapour mole fraction of A is","options":["0.40","0.24","0.60","1.0"],"answer_index":0,"explanation":"$y_A = p_A / p_{\\mathrm{total}} = 24/60 = 0.40$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-168","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Component B is non-volatile. If $x_{\\mathrm{solvent}} = 0.95$ and $p^\\circ_{\\mathrm{solvent}} = 20$ kPa, the solution vapour pressure equals","options":["19 kPa","20 kPa","1 kPa","21 kPa"],"answer_index":0,"explanation":"$p = 20 \\times 0.95 = 19$ kPa.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-169","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two ideal liquids are present in equal mole fractions. $p_A^\\circ = 90$ torr and $p_B^\\circ = 60$ torr. Total vapour pressure is","options":["75 torr","150 torr","90 torr","30 torr"],"answer_index":0,"explanation":"$p = 0.50 \\times 90 + 0.50 \\times 60 = 75$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-170","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Vapour over an ideal mix is analysed as $y_A = 0.70$ when $p_{\\mathrm{total}} = 100$ torr. Partial pressure of A in that vapour is","options":["70 torr","30 torr","100 torr","0.70 torr"],"answer_index":0,"explanation":"$p_A = y_A p_{\\mathrm{total}} = 0.70 \\times 100 = 70$ torr.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"raoult-vapour","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
